"""Inspect the workspace: list files and, if present, inspect SQLite databases."""
import os
import sqlite3

for name in sorted(os.listdir(".")):
    print(("DIR  " if os.path.isdir(name) else "FILE ") + name)

for name in sorted(os.listdir(".")):
    if name.endswith((".db", ".sqlite", ".sqlite3")):
        print("\n=== schema of", name, "===")
        try:
            with sqlite3.connect(name) as conn:
                rows = conn.execute(
                    "SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL"
