"""Inspect the workspace for a SQLite database and report its schema.

Task-scoped helper: only reads local files and opens the SQLite database
read-only via introspection queries. No modifications are made.
"""
import os
import sqlite3

DB_SUFFIXES = (".db", ".sqlite", ".sqlite3", ".db3")


def find_databases(root="."):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        # Skip hidden/private dirs (git, venvs, caches) to reduce noise.
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]
        for name in filenames:
            if name.lower().endswith(DB_SUFFIXES):
                found.append(os.path.join(dirpath, name))
    return found


def describe(db_path):
    print(f"\n=== {db_path} ===")
    uri = f"file:{os.path.abspath(db_path)}?mode=ro"
    with sqlite3.connect(uri, uri=True) as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        tables = cur.execute(
            "SELECT name, sql FROM sqlite_master WHERE type='table' ORDER BY name"
        ).fetchall()
        if not tables:
            print("  (no tables)")
        for t in tables:
            print(f"TABLE: {t['name']}")
            print(f"  SQL: {t['sql']}")
            try:
                cols = cur.execute(
                    f'PRAGMA table_info("{t["name"]}")'
                ).fetchall()
                for c in cols:
                    print(
                        f"    column: {c['name']} {c['type']} "
                        f"notnull={c['notnull']} default={c['default']!r} pk={c['pk']}"
                    )
                row_count = cur.execute(
                    f'SELECT COUNT(*) FROM "{t["name"]}"'
                ).fetchone()[0]
                print(f"    rows: {row_count}")
            except sqlite3.Error as e:
                print(f"    error reading details: {e}")
        triggers = cur.execute(
            "SELECT name FROM sqlite_master WHERE type='trigger'"
        ).fetchall()
        if triggers:
            print("  triggers:", [r["name"] for r in triggers])


def main():
    print("CWD:", os.getcwd())
    print("Top-level entries:", sorted(os.listdir(".")))
    dbs = find_databases()
    if not dbs:
        print("No SQLite database files found.")
        return
    for db in dbs:
        describe(db)


if __name__ == "__main__":
    main()

